A.LINES = [{"id": "ann1", "who": "ANNOUNCER", "t": 1.2, "end": 4.861, "text": "Eighty-nine minutes gone, one all, and Maccabi are on the attack!", "he": "דקה 89, אחת-אחת, ומכבי בהתקפה!", "words": [{"w": "Eighty-nine", "t": 1.2}, {"w": "minutes", "t": 1.868}, {"w": "gone,", "t": 2.322}, {"w": "one", "t": 2.616}, {"w": "all,", "t": 2.857}, {"w": "and", "t": 3.097}, {"w": "Maccabi", "t": 3.338}, {"w": "are", "t": 3.792}, {"w": "on", "t": 4.033}, {"w": "the", "t": 4.22}, {"w": "attack!", "t": 4.46}]}, {"id": "saba1", "who": "SABA", "t": 6.9, "end": 10.235, "text": "Noa! Eighty-nine minutes. One one. This is it.", "he": "נועה! דקה 89. אחת-אחת. זהו זה.", "words": [{"w": "Noa!", "t": 6.9}, {"w": "Eighty-nine", "t": 7.219}, {"w": "minutes.", "t": 8.106}, {"w": "One", "t": 8.709}, {"w": "one.", "t": 9.028}, {"w": "This", "t": 9.348}, {"w": "is", "t": 9.738}, {"w": "it.", "t": 9.986}]}, {"id": "noa1", "who": "NOA", "t": 10.5, "end": 12.408, "text": "Saba, breathe. It's just football.", "he": "סבא, תנשום. זה רק כדורגל.", "words": [{"w": "Saba,", "t": 10.5}, {"w": "breathe.", "t": 10.804}, {"w": "It's", "t": 11.274}, {"w": "just", "t": 11.579}, {"w": "football.", "t": 11.883}]}, {"id": "saba2", "who": "SABA", "t": 12.6, "end": 14.708, "text": "Just football?! Go, Maccabi!", "he": "רק כדורגל?! קדימה מכבי!", "words": [{"w": "Just", "t": 12.6}, {"w": "football?!", "t": 13.029}, {"w": "Go,", "t": 13.771}, {"w": "Maccabi!", "t": 14.045}]}, {"id": "saba3", "who": "SABA", "t": 15.2, "end": 16.542, "text": "No! Not now!", "he": "לא! רק לא עכשיו!", "words": [{"w": "No!", "t": 15.2}, {"w": "Not", "t": 15.576}, {"w": "now!", "t": 16.059}]}, {"id": "noa2", "who": "NOA", "t": 17.6, "end": 19.7, "text": "Hold on, Saba. I'll find where it's stuck.", "he": "רגע, סבא. אני אמצא איפה זה תקוע.", "words": [{"w": "Hold", "t": 17.6}, {"w": "on,", "t": 17.863}, {"w": "Saba.", "t": 18.03}, {"w": "I'll", "t": 18.292}, {"w": "find", "t": 18.555}, {"w": "where", "t": 18.817}, {"w": "it's", "t": 19.127}, {"w": "stuck.", "t": 19.39}]}, {"id": "bit1", "who": "BIT", "t": 21.9, "end": 23.881, "text": "Excuse me! Live goal coming through! Live goal!", "he": "סליחה! גול חי עובר! גול חי!", "words": [{"w": "Excuse", "t": 21.9}, {"w": "me!", "t": 22.203}, {"w": "Live", "t": 22.345}, {"w": "goal", "t": 22.567}, {"w": "coming", "t": 22.789}, {"w": "through!", "t": 23.093}, {"w": "Live", "t": 23.436}, {"w": "goal!", "t": 23.658}]}, {"id": "cat1", "who": "CATPACKET", "t": 25.1, "end": 27.602, "text": "Get in line, kid. Cat videos first.", "he": "תעמוד בתור, ילד. סרטוני חתולים קודם.", "words": [{"w": "Get", "t": 25.1}, {"w": "in", "t": 25.408}, {"w": "line,", "t": 25.648}, {"w": "kid.", "t": 26.025}, {"w": "Cat", "t": 26.334}, {"w": "videos", "t": 26.642}, {"w": "first.", "t": 27.156}]}, {"id": "bit2", "who": "BIT", "t": 28.0, "end": 28.688, "text": "Not today!", "he": "לא היום!", "words": [{"w": "Not", "t": 28.0}, {"w": "today!", "t": 28.282}]}, {"id": "bit3", "who": "BIT", "t": 32.2, "end": 33.907, "text": "Marseille... the Atlantic... whoa, shark!", "he": "מרסיי... האטלנטי... וואו, כריש!", "words": [{"w": "Marseille...", "t": 32.2}, {"w": "the", "t": 32.691}, {"w": "Atlantic...", "t": 32.902}, {"w": "whoa,", "t": 33.346}, {"w": "shark!", "t": 33.603}]}, {"id": "bit4", "who": "BIT", "t": 37.6, "end": 38.585, "text": "Nice try, fishy!", "he": "יפה ניסית, דגיג!", "words": [{"w": "Nice", "t": 37.6}, {"w": "try,", "t": 37.928}, {"w": "fishy!", "t": 38.197}]}, {"id": "bit5", "who": "BIT", "t": 41.9, "end": 43.397, "text": "Last mile... last meter...", "he": "הקילומטר האחרון... המטר האחרון...", "words": [{"w": "Last", "t": 41.9}, {"w": "mile...", "t": 42.258}, {"w": "last", "t": 42.616}, {"w": "meter...", "t": 42.974}]}, {"id": "bit6", "who": "BIT", "t": 44.6, "end": 45.291, "text": "Delivered!", "he": "נמסר!", "words": [{"w": "Delivered!", "t": 44.6}]}, {"id": "ann2", "who": "ANNOUNCER", "t": 46.6, "end": 47.754, "text": "Goooal! Maccabi!", "he": "גוווול! מכבי!", "words": [{"w": "Goooal!", "t": 46.6}, {"w": "Maccabi!", "t": 47.141}]}, {"id": "saba4", "who": "SABA", "t": 48.3, "end": 50.477, "text": "Gooool! Noa, you are a genius!", "he": "גוווול! נועה, את גאונה!", "words": [{"w": "Gooool!", "t": 48.3}, {"w": "Noa,", "t": 48.81}, {"w": "you", "t": 49.116}, {"w": "are", "t": 49.423}, {"w": "a", "t": 49.729}, {"w": "genius!", "t": 49.967}]}, {"id": "noa3", "who": "NOA", "t": 51.4, "end": 52.846, "text": "Thank the little packet, Saba.", "he": "תודה לחבילה הקטנה, סבא.", "words": [{"w": "Thank", "t": 51.4}, {"w": "the", "t": 51.698}, {"w": "little", "t": 51.905}, {"w": "packet,", "t": 52.249}, {"w": "Saba.", "t": 52.594}]}, {"id": "bit7", "who": "BIT", "t": 55.0, "end": 56.846, "text": "Next time... send the goal earlier.", "he": "בפעם הבאה... תשלחו את הגול מוקדם יותר.", "words": [{"w": "Next", "t": 55.0}, {"w": "time...", "t": 55.29}, {"w": "send", "t": 55.58}, {"w": "the", "t": 55.87}, {"w": "goal", "t": 56.107}, {"w": "earlier.", "t": 56.397}]}];
